mapper.select:
select * from (
select
t.id,
t.card_id,
t.bank_card_id,
t.bank_card_name,
t.transaction_date,
t.bookkeeping_date,
t.transaction_desc,
t.balance_currency,
t.balance_money,
t.card_type_id,
t.card_type_name,
t.consumption_type,
t.consume_id,
t.consume_code,
t.consume_name,
t.demoarea,
t.recordid,
t.income_money,
t.opponent_account,
t.opponent_name,
t.transaction_time,
t.account_balance
from transaction t
left join consume_category cat on cat.code = t.consume_code and cat.deleted != 1
where 1 = 1


        and cat.txn_types like CONCAT('%', #{q.txnTypes,jdbcType=VARCHAR}, '%')


        and t.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}


        and t.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}


        and t.consumption_type = #{q.consumptionType,jdbcType=NUMERIC}


        and t.bank_card_id = #{q.bankCardId,jdbcType=VARCHAR}


        and t.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}


        and t.consume_id = #{q.consumeID,jdbcType=VARCHAR}


        and t.consume_code = #{q.consumeCode,jdbcType=VARCHAR}


        and t.consume_code in

            #{consumeID,jdbcType=VARCHAR}



        and (t.consume_name is null or length(trim(t.consume_name)) = 0 or t.consume_code is null or length(trim(t.consume_code)) = 0)


        and t.consume_name = #{q.consumeName,jdbcType=VARCHAR}


        and (
            t.demoarea like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%')
            or t.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%')
        )


        and weekday(t.bookkeeping_date) = #{q.weekName,jdbcType=VARCHAR}


        and year(t.transaction_date) = #{q.year,jdbcType=VARCHAR}


        and month(t.transaction_date) = #{q.month,jdbcType=VARCHAR}


order by t.transaction_date desc
) t limit #{page.recordBegin,jdbcType=NUMERIC}, #{page.pageSize,jdbcType=NUMERIC}

select count(t.id) from transaction t
left join consume_category cat on cat.code = t.consume_code and cat.deleted != 1
where 1 = 1


        and cat.txn_types like CONCAT('%', #{q.txnTypes,jdbcType=VARCHAR}, '%')


        and t.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}


        and t.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}


        and t.consumption_type = #{q.consumptionType,jdbcType=NUMERIC}


        and t.bank_card_id = #{q.bankCardId,jdbcType=VARCHAR}


        and t.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}


        and t.consume_id = #{q.consumeID,jdbcType=VARCHAR}


        and t.consume_code = #{q.consumeCode,jdbcType=VARCHAR}


        and t.consume_code in

            #{consumeID,jdbcType=VARCHAR}



        and (t.consume_name is null or length(trim(t.consume_name)) = 0 or t.consume_code is null or length(trim(t.consume_code)) = 0)


        and t.consume_name = #{q.consumeName,jdbcType=VARCHAR}


        and (t.demoarea like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%')
        or t.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )


        and weekday(t.bookkeeping_date) = #{q.weekName,jdbcType=VARCHAR}


        and year(t.transaction_date) = #{q.year,jdbcType=VARCHAR}


        and month(t.transaction_date) = #{q.month,jdbcType=VARCHAR}

select round(abs(sum(c.balance_money))) as `value`, case when (isnull(c.consume_name)=1 or length(trim(c.consume_name))=0) then 'unkown' else c.consume_name end as `key` from transaction c left join consume_category cat on cat.code = c.consume_code and cat.deleted != 1 where 1 = 1
and cat.txn_types like CONCAT('%', #{q.txnTypes,jdbcType=VARCHAR}, '%')
and cat.txn_types like '%expense%'
and c.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}
and c.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and c.consume_code in
#{consumeID,jdbcType=VARCHAR}
and (c.demoarea like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
group by case when (isnull(c.consume_name)=1 or length(trim(c.consume_name))=0) then 'unkown' else c.consume_name end order by `key`

select round(abs(sum(balance_money))) as `value`, wday as `key` from ( select weekday(c.bookkeeping_date) wday, c.balance_money from transaction c left join consume_category cat on cat.code = c.consume_code and cat.deleted != 1 where 1 = 1
and cat.txn_types like CONCAT('%', #{q.txnTypes,jdbcType=VARCHAR}, '%')
and cat.txn_types like '%expense%'
and c.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}
and c.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and c.consume_code in
#{consumeID,jdbcType=VARCHAR}
and (c.demoarea like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
) view1 group by wday order by wday

select round(abs(balance_money)) 'value', case when cmonth = 1 then 'January' when cmonth = 2 then 'February' when cmonth = 3 then 'March' when cmonth = 4 then 'April' when cmonth = 5 then 'May' when cmonth = 6 then 'June' when cmonth = 7 then 'July' when cmonth = 8 then 'August' when cmonth = 9 then 'September' when cmonth = 10 then 'October' when cmonth = 11 then 'November' when cmonth = 12 then 'December' else cmonth end 'key' from (select sum(balance_money) balance_money,cmonth from (select c.balance_money, month(c.transaction_date) cmonth from transaction c left join consume_category cat on cat.code = c.consume_code and cat.deleted != 1 where 1 = 1
and cat.txn_types like CONCAT('%', #{q.txnTypes,jdbcType=VARCHAR}, '%')
and cat.txn_types like '%expense%'
and year(c.transaction_date) = #{q.year,jdbcType=VARCHAR}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and c.consume_code in
#{consumeID,jdbcType=VARCHAR}
and (c.demoarea like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
) t1 group by cmonth) t2 order by cmonth

select round(sum(amount)) as `value`, case when cmonth = 1 then 'January' when cmonth = 2 then 'February' when cmonth = 3 then 'March' when cmonth = 4 then 'April' when cmonth = 5 then 'May' when cmonth = 6 then 'June' when cmonth = 7 then 'July' when cmonth = 8 then 'August' when cmonth = 9 then 'September' when cmonth = 10 then 'October' when cmonth = 11 then 'November' when cmonth = 12 then 'December' else cmonth end as `key` from ( select month(c.transaction_date) as cmonth, case when (coalesce(c.income_money,0) > 0) then coalesce(c.income_money,0) when (coalesce(c.balance_money,0) < 0) then abs(coalesce(c.balance_money,0)) else 0 end as amount from transaction c left join consume_category cat on cat.code = c.consume_code and cat.deleted != 1 where 1 = 1
and year(c.transaction_date) = #{q.year,jdbcType=VARCHAR}
and c.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}
and c.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and c.consume_code in
#{consumeID,jdbcType=VARCHAR}
and (c.demoarea like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
and ( coalesce(c.income_money,0) > 0 or coalesce(c.balance_money,0) < 0 or (cat.txn_types is not null and cat.txn_types like '%income%') )
) t group by cmonth order by cmonth

select round(sum(amount)) as `value`, case when cmonth = 1 then 'January' when cmonth = 2 then 'February' when cmonth = 3 then 'March' when cmonth = 4 then 'April' when cmonth = 5 then 'May' when cmonth = 6 then 'June' when cmonth = 7 then 'July' when cmonth = 8 then 'August' when cmonth = 9 then 'September' when cmonth = 10 then 'October' when cmonth = 11 then 'November' when cmonth = 12 then 'December' else cmonth end as `key` from ( select month(c.transaction_date) as cmonth, case when (coalesce(c.balance_money,0) > 0) then coalesce(c.balance_money,0) else 0 end as amount from transaction c left join consume_category cat on cat.code = c.consume_code and cat.deleted != 1 where 1 = 1
and year(c.transaction_date) = #{q.year,jdbcType=VARCHAR}
and c.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}
and c.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and c.consume_code in
#{consumeID,jdbcType=VARCHAR}
and (c.demoarea like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
and (coalesce(c.balance_money,0) > 0 or (cat.txn_types is not null and cat.txn_types like '%expense%'))
) t group by cmonth order by cmonth

select count(1) from transaction t
where year(t.transaction_date) = #{year,jdbcType=NUMERIC}
  and (t.transaction_desc like '%退款%' or t.demoarea like '%退款%')
